1	/**
2	 * Organization Module — single source of truth for departments, phases, and
3	 * the agent registry. Replaces the hardcoded AGENT_PIPELINE / AGENT_ROLES
4	 * constants previously in server.js.
5	 *
6	 * Data lives in ~/.claude/org/:
7	 *   - departments.json — department + phase definitions
8	 *   - registry.json    — per-agent record (department, phase, reportsTo,
9	 *                        experience, level, skills, status, hire date)
10	 *
11	 * This module is pure — it reads/writes JSON. Experience computation lives
12	 * in src/experience.js and reads from here.
13	 */
14	
15	const fs = require('fs');
16	const path = require('path');
17	const os = require('os');
18	
19	const HOME = os.homedir();
20	const ORG_DIR = path.join(HOME, '.claude', 'org');
21	const DEPARTMENTS_PATH = path.join(ORG_DIR, 'departments.json');
22	const REGISTRY_PATH = path.join(ORG_DIR, 'registry.json');
23	
24	function ensureDir(dir) {
25	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
26	}
27	
28	function readJson(filePath, fallback) {
29	  try {
30	    if (!fs.existsSync(filePath)) return fallback;
31	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
32	  } catch (err) {
33	    console.warn(`[org] failed to read ${filePath}: ${err.message}`);
34	    return fallback;
35	  }
36	}
37	
38	function writeJson(filePath, data) {
39	  ensureDir(path.dirname(filePath));
40	  // Atomic write: write to .tmp then rename
41	  const tmp = filePath + '.tmp';
42	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
43	  fs.renameSync(tmp, filePath);
44	}
45	
46	// ──────────────────────────────────────────────────────────────────────────
47	//  Departments & Phases
48	// ──────────────────────────────────────────────────────────────────────────
49	
50	function loadDepartments() {
51	  const raw = readJson(DEPARTMENTS_PATH, { departments: {}, phases: {} });
52	  return raw;
53	}
54	
55	function saveDepartments(data) {
56	  data.updatedAt = new Date().toISOString();
57	  writeJson(DEPARTMENTS_PATH, data);
58	}
59	
60	function listDepartments() {
61	  const { departments } = loadDepartments();
62	  return Object.values(departments || {})
63	    .filter((d) => d.active !== false)
64	    .sort((a, b) => (a.order || 0) - (b.order || 0));
65	}
66	
67	function getDepartment(id) {
68	  const { departments } = loadDepartments();
69	  return departments?.[id] || null;
70	}
