309	  getPhase,
310	
311	  // registry
312	  loadRegistry,
313	  saveRegistry,
314	  listAgentRecords,
315	  findAgent,
316	  upsertAgent,
317	  removeAgent,
318	  findAgentsByDepartment,
319	  findAgentsByPhase,
320	  findDirectReports,
321	
322	  // compose
323	  buildOrgChart,
324	  detectDrift,
325	};
